// Meta only sends an id - the lead body is fetched separately. Validate first:
// a webhook with no leadgen_id is either a test ping or someone probing your URL.
return $input.all().map((item) => {
  const body = item.json.body || item.json;
  const headers = item.json.headers || {};
  const entry = (body.entry && body.entry[0]) || {};
  const change = (entry.changes && entry.changes[0]) || {};
  const value = change.value || {};
  const valid = Boolean(value.leadgen_id) && Boolean(headers['x-hub-signature-256']);
  return { json: {
    valid,
    reason: valid ? 'ok' : 'missing leadgen_id or x-hub-signature-256 header',
    leadgen_id: value.leadgen_id || '',
    form_id: value.form_id || '',
    page_id: value.page_id || '',
    campaign: value.ad_id || ''
  } };
});

// field_data is an array of {name, values:[]}. Flatten it, then map to the neutral shape.
return $input.all().map((item) => {
  const flat = {};
  for (const f of item.json.field_data || []) {
    flat[String(f.name).toLowerCase()] = Array.isArray(f.values) ? f.values[0] : f.values;
  }
  const lead = {
    email: String(flat.email || flat.work_email || '').trim().toLowerCase(),
    phone: String(flat.phone_number || flat.phone || '').trim(),
    name: String(flat.full_name || [flat.first_name, flat.last_name].filter(Boolean).join(' ') || '').trim(),
    company: String(flat.company_name || '').trim(),
    source: 'facebook_lead_ads',
    campaign: item.json.ad_id || '',
    // Lead Ads carry the consent the user gave on the form itself.
    consent_basis: 'consent',
    consent_recorded_at: item.json.created_time || new Date().toISOString(),
    requested_call: /call|quote|demo/i.test(JSON.stringify(flat)),
    received_at: new Date().toISOString()
  };
  if (!lead.email && !lead.phone) throw new Error('Lead Ads form returned neither email nor phone.');
  return { json: { lead } };
});

// Build the request the rails expect. Missing fields are denied, not defaulted:
// the rails fail closed on purpose.
return $input.all().map((item) => {
  const lead = item.json.lead || item.json;
  return { json: Object.assign({}, item.json, { rails_request: {
    channel: 'email',
    purpose: 'instant_reply',
    contact_email: lead.email || '',
    contact_phone: lead.phone || '',
    contact_handle: lead.handle || '',
    inbound_message: lead.last_inbound_message || '',
    consent: { basis: lead.consent_basis || null, recorded_at: lead.consent_recorded_at || null },
    estimated_cost_usd: Number(lead.estimated_cost_usd || 0),
    workflow: $workflow.name
  } }) };
});

// The rails said no. Record it and stop. A denied action is never retried.
return $input.all().map((item) => ({ json: {
  blocked: true,
  code: item.json.code || 'denied',
  reason: item.json.reason || 'Safety rails denied this action.',
  contact: item.json.rails_request ? item.json.rails_request.contact_email : null,
  workflow: $workflow.name,
  at: new Date().toISOString()
} }));

